class Order {
 public:
  explicit Order(OrderId id, long credit_limit_cents)
      : id_(id), credit_limit_cents_(credit_limit_cents) {}
  void add_line(OrderLine line) {
    if (total_cents_ + line.amount_cents() > credit_limit_cents_)
      throw CreditLimitExceeded{};
    total_cents_ += line.amount_cents();
    lines_.push_back(std::move(line));      // invariant re-established here
  }
  const std::vector<OrderLine>& lines() const { return lines_; }  // read-only view
 private:
  OrderId id_; long total_cents_{0}, credit_limit_cents_{0};
  std::vector<OrderLine> lines_;
};
